style.css:
body, html {
  height: 100%;
  margin: 0;
  padding: 0;
  background: url("https://wallpapercave.com/wp/wp15840838.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
  color: #eee !important;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
}

body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.6);
  pointer-events: none;
  z-index: -1;
}
